using System.Linq;
using System.Text;
using DialogEdit;
using LootEdit;
using LootEdit.loot;
namespace ProjectTower.player.dialog;
public class DialogMenuItem
{
	public int idx;
	public int selX;
	public float sel;
	public bool locked;
	public bool inactive;
	public bool lockedClickable;
	public bool isDoneOption;
	public StringBuilder[] str;
	public StringBuilder lockStr;
	public StringBuilder giveStr;
	public LootDef lDef;
	public DialogMenuItem(int idx, string str, Player p)
	{
		Init(idx, str, null, p);
	}
	public DialogMenuItem(int idx, string str, string localStr, Player p)
	{
		Init(idx, str, localStr, p);
	}
	public void Init(int idx, string str, string localStr, Player p)
	{
		this.idx = idx;
		lDef = null;
		giveStr = null;
		if (str.Contains("Done"))
		{
			isDoneOption = true;
		}
		if (localStr != null && localStr.Contains('|'))
		{
			localStr = localStr.Split('|')[0].Trim();
		}
		if (str.Contains('|'))
		{
			string[] array = str.Split('|');
			str = array[0];
			for (int i = 0; i < 8; i++)
			{
				for (int j = 0; j < LootCatalog.category[i].loot.Length; j++)
				{
					if (LootCatalog.category[i].loot[j].name == array[1])
					{
						lDef = LootCatalog.category[i].loot[j];
						break;
					}
				}
				if (lDef != null)
				{
					break;
				}
			}
		}
		if (localStr != null)
		{
			str = localStr;
		}
		if (lDef != null)
		{
			this.str = new StringBuilder[1]
			{
				new StringBuilder(str)
			};
			giveStr = new StringBuilder(str + " (" + LocStrings.GetLocStr(455) + " " + lDef.title[Game1.language] + ")");
			lockStr = new StringBuilder("\u0081" + str + " (" + LocStrings.GetLocStr(454) + " " + lDef.title[Game1.language] + ")");
		}
		else
		{
			this.str = new StringBuilder[1]
			{
				new StringBuilder(str)
			};
			lockStr = new StringBuilder("\u0081" + str);
		}
		if (lDef == null || p == null)
		{
			return;
		}
		locked = true;
		for (int k = 0; k < p.playerInv.inventory.Length; k++)
		{
			if (p.playerInv.inventory[k] != null && LootCatalog.category[p.playerInv.inventory[k].category].loot[p.playerInv.inventory[k].catalogIdx].name == lDef.name)
			{
				locked = false;
				break;
			}
		}
	}
}
using System;
using System.Text;
using MapEdit;
using Microsoft.Xna.Framework;
using ProjectTower.audio;
using ProjectTower.gamestate;
using ProjectTower.hud;
using ProjectTower.menu;
namespace ProjectTower.player.dialog;
public class DialogMenuLevel
{
	public DialogMenuItem[] item;
	public const string MENU = "menu";
	public int selected;
	public int showParent = -1;
	public Vector2 off;
	public StringBuilder title;
	public StringBuilder[] infos;
	public float alpha;
	public bool hijackDraw;
	public bool hijackUpdate;
	public bool horizontalButtons;
	public const int SPECIAL_UPDATE_NONE = 0;
	public const int SPECIAL_UPDATE_CHAR_SELECT = 1;
	public int specialUpdate;
	public bool showTitle;
	public virtual void Select(Player p)
	{
	}
	public virtual void LockedSelect(Player p)
	{
	}
	public virtual void Cancel(Player p)
	{
	}
	public virtual void SelectedUpdate(Player p)
	{
	}
	public virtual void SelectedDraw(float scale, float alpha, int xOffset, Player p)
	{
	}
	public virtual void Update(int ID, Player p)
	{
		if (p.dialog.menuMgr.curLev == ID)
		{
			switch (p.dialog.menuMgr.transMode)
			{
			}
		}
		if (!HUD.IsDialogActive(p) && p.dialog.menuMgr.curLev == ID)
		{
			SelectedUpdate(p);
		}
		if (!hijackUpdate && !HUD.IsDialogActive(p) && p.dialog.menuMgr.curLev == ID && p.dialog.menuMgr.transMode == 0)
		{
			int iD = p.ID;
			if (item.Length != 0)
			{
				if (horizontalButtons)
				{
					if (p.menuMgr.keys.GetLeft(iD) > -1)
					{
						selected = (selected + item.Length - 1) % item.Length;
						Sound.PlaySelect();
					}
					if (p.menuMgr.keys.GetRight(iD) > -1)
					{
						selected = (selected + 1) % item.Length;
						Sound.PlaySelect();
					}
				}
				else
				{
					if (p.menuMgr.keys.GetUp(iD) > -1)
					{
						selected = (selected + item.Length - 1) % item.Length;
						Sound.PlaySelect();
					}
					if (p.menuMgr.keys.GetDown(iD) > -1)
					{
						selected = (selected + 1) % item.Length;
						Sound.PlaySelect();
					}
					if (p.menuMgr.keys.GetLeft(iD) > -1 && !item[selected].inactive && !item[selected].locked)
					{
						if (item[selected].selX > 0)
						{
							item[selected].selX--;
							item[selected].sel = 0.25f;
						}
						Sound.PlaySelect();
					}
					if (p.menuMgr.keys.GetRight(iD) > -1 && !item[selected].inactive && !item[selected].locked)
					{
						if (item[selected].selX < item[selected].str.Length - 1)
						{
							item[selected].selX++;
							item[selected].sel = 0.25f;
						}
						Sound.PlaySelect();
					}
				}
			}
			int num = -1;
			if (iD > -1)
			{
				num = p.menuMgr.keys.GetAccept(iD);
				if (p.keyBCancel)
				{
					for (int i = 0; i < item.Length; i++)
					{
						if (item[i].lockStr.ToString().Contains("Done") || item[i].isDoneOption)
						{
							num = i;
							selected = i;
						}
					}
				}
			}
			if (num > -1)
			{
				if (selected > -1 && selected < item.Length)
				{
					if (!item[selected].inactive && !item[selected].locked)
					{
						Select(p);
						Sound.PlayAccept();
					}
					else if (!item[selected].inactive && item[selected].locked && item[selected].lockedClickable)
					{
						LockedSelect(p);
						Sound.PlayAccept();
					}
					else
					{
						Sound.PlayAccept();
					}
				}
				else
				{
					Select(p);
				}
			}
			else if (iD > -1)
			{
				num = p.menuMgr.keys.GetCancel(iD);
				if (num > -1 && p.menuMgr.curLev != 0)
				{
					Cancel(p);
					Sound.PlayCancel();
				}
			}
			for (int j = 0; j < item.Length; j++)
			{
				if (j == selected)
				{
					if (item[j].sel < 1f)
					{
						item[j].sel += Game1.frameTime * 9f;
						if (item[j].sel > 1f)
						{
							item[j].sel = 1f;
						}
					}
				}
				else if (item[j].sel > 0f)
				{
					item[j].sel -= Game1.frameTime * 9f;
					if (item[j].sel < 0f)
					{
						item[j].sel = 0f;
					}
				}
			}
		}
		if (p.dialog.menuMgr.curLev == ID)
		{
			if (showParent > -1)
			{
				p.dialog.menuMgr.menuLevel[showParent].alpha = 1f;
			}
			switch (p.dialog.menuMgr.transMode)
			{
			case 0:
				alpha = 1f;
				break;
			case 1:
			case 3:
				alpha = 1f - p.dialog.menuMgr.transFrame;
				if (showParent > -1)
				{
					if (p.dialog.menuMgr.transLevel != showParent)
					{
						p.dialog.menuMgr.menuLevel[showParent].alpha = alpha;
					}
					if (p.draw.upgradeFrame > 0f)
					{
						p.dialog.menuMgr.menuLevel[showParent].alpha = alpha;
					}
				}
				break;
			case 2:
			case 4:
				alpha = p.dialog.menuMgr.transFrame;
				break;
			}
		}
		else if (p.dialog.menuMgr.menuLevel[p.dialog.menuMgr.curLev].showParent == ID)
		{
			alpha = 1f;
			if (p.draw.upgradeFrame > 0f)
			{
				alpha = p.dialog.menuMgr.menuLevel[p.dialog.menuMgr.curLev].alpha;
			}
		}
		else
		{
			alpha = 0f;
		}
	}
	public virtual void DrawBottomRightButtons()
	{
		BottomRightMessage.DrawButton(0, 1, 1f);
		BottomRightMessage.DrawButton(1, 0, 1f);
	}
	public static Rectangle CoopAdjustRect(Rectangle dRect, Player p, int xOff)
	{
		if (GameStateManager.coopPlayerIdx > -1)
		{
			if (!GameStateManager.splitScreenCoopMode)
			{
				if (p.ID == GameStateManager.mainPlayerIdx)
				{
					dRect.X = (int)(ScrollManager.screenSize.X * 0.25f - (float)(dRect.Width / 2));
				}
				else
				{
					dRect.X = (int)(ScrollManager.screenSize.X * 0.75f - (float)(dRect.Width / 2));
				}
				return dRect;
			}
			dRect.X -= 140;
		}
		return dRect;
	}
	public virtual void Draw(Player p, float scale)
	{
		if (alpha <= 0f)
		{
			return;
		}
		int num = 0;
		if (GameStateManager.coopPlayerIdx > -1 && !GameStateManager.splitScreenCoopMode)
		{
			if (p.ID == GameStateManager.mainPlayerIdx)
			{
				num -= (int)(ScrollManager.totalScreenSize.X * 0.5f);
			}
			num += (int)(ScrollManager.totalScreenSize.X * 0.15f);
		}
		SelectedDraw(scale, alpha, num, p);
		if (hijackDraw)
		{
			return;
		}
		int num2 = 38;
		float num3 = 0f;
		for (int i = 0; i < item.Length; i++)
		{
			StringBuilder s;
			if (item[i].locked)
			{
				s = item[i].lockStr;
			}
			else
			{
				s = ((item[i].giveStr != null) ? item[i].giveStr : item[i].str[item[i].selX]);
			}
			float stringSpace = Text.GetStringSpace(s, 0.48000002f, p, 0);
			if (stringSpace > num3)
			{
				num3 = stringSpace;
			}
		}
		num3 += 60f;
		Rectangle rect = new Rectangle((int)(ScrollManager.screenSize.X / 2f + 200f * scale), 0, (int)(num3 * scale), (int)((float)(item.Length * num2) * scale + 24f * scale));
		rect.Y = (int)ScrollManager.screenSize.Y / 2 - rect.Height / 2;
		if (GameStateManager.coopPlayerIdx > -1 && GameStateManager.splitScreenCoopMode)
		{
			rect.X -= 100;
		}
		rect.X += num;
		InterfaceRender.DrawRect(rect, alpha * 0.8f);
		if (showTitle)
		{
			DrawTitle(rect.X);
		}
		for (int j = 0; j < item.Length; j++)
		{
			float num4 = item[j].sel * 0.6f;
			float num5 = 0.6f;
			float num6 = (float)rect.Y + (float)j * (float)num2 * scale + 28f * scale;
			float num7 = alpha;
			float num8 = num4 + 0.5f;
			StringBuilder s2;
			if (item[j].locked)
			{
				s2 = item[j].lockStr;
			}
			else
			{
				s2 = ((item[j].giveStr != null) ? item[j].giveStr : item[j].str[item[j].selX]);
			}
			Text.DrawText(s2, new Vector2((float)rect.X + 40f * scale, num6), new Color(num8, num8, num8, num7), num5 * scale, 0);
			Rectangle rectangle = new Rectangle(rect.X + 4, (int)num6 - 20, rect.Width - 10, 42);
			if (MouseMgr.IsMouseInRect(p, rectangle))
			{
				selected = j;
				if (MouseMgr.isClick)
				{
					p.keyQueueAccept = true;
				}
			}
			if (item[j].sel > 0f)
			{
				InterfaceRender.DrawRect(rectangle, item[j].sel * 0.1f * num7, 1);
				Text.DrawText(InterfaceRender.CHAR_A, new Vector2(rect.X, num6), new Color(1f, 1f, 1f, item[j].sel * num7), num5 * scale, 0, p, 5);
			}
		}
	}
	public void DrawTitle(float x)
	{
		Text.DrawText(title, off + new Vector2(x, -100f), new Color(1f, 1f, 1f, alpha), 0.65f, 0);
		if (infos != null)
		{
			for (int i = 0; i < infos.Length; i++)
			{
				Text.DrawText(infos[i], off + new Vector2(x, 190f + (float)i * 40f), new Color(1f, 0.8f, 0.8f, alpha), 0.7f, 1);
			}
		}
	}
	protected static Rectangle CoopAdjustX(int p)
	{
		throw new NotImplementedException();
	}
}
using ProjectTower.character;
using ProjectTower.map;
using ProjectTower.player.dialog.levels;
namespace ProjectTower.player.dialog;
public class DialogMenuMgr
{
	public DialogMenuLevel[] menuLevel;
	public const int LEVEL_ICON_OFFER = 0;
	public const int LEVEL_BUY_YOU_SURE = 1;
	public const int LEVEL_ACCEPT_TRANSMUTATION = 2;
	public const int LEVEL_FAST_TRAVEL = 3;
	public const int LEVEL_ICON_MAIN = 4;
	public const int LEVEL_STORE = 5;
