	public void DoLevelTrans(int level)
	{
		if (transMode == 0)
		{
			transLevel = level;
			transMode = 1;
			transFrame = 0f;
			if (menuLevel[level].showParent == curLev)
			{
				curLev = level;
				transMode = 2;
				transFrame = 0f;
			}
		}
	}
	public void DoSpecialTrans(int level)
	{
		if (transMode == 0)
		{
			transSpecial = level;
			transMode = 3;
			transFrame = 0f;
		}
	}
	public void Update()
	{
		switch (transMode)
		{
		case 1:
			transFrame += Game1.frameTime * 4f;
			if (!(transFrame > 1f))
			{
				break;
			}
			if (menuLevel[curLev].showParent == transLevel)
			{
				if (!(p.draw.upgradeFrame > 0f))
				{
					curLev = transLevel;
					transMode = 0;
					transFrame = 0f;
				}
			}
			else
			{
				curLev = transLevel;
				transFrame = 0f;
				transMode = 2;
			}
			break;
		case 3:
			transFrame += Game1.frameTime * 4f;
			if (!(transFrame > 1f))
			{
				break;
			}
			MapMgr.sanctuaryMgr.GetSanctuaryCreed(p);
			switch (transSpecial)
			{
			case 100:
				active = false;
				NPCDialogCatalog.DoDialog(p.dialog.dialogCatIdx, p.dialog.dialogCatNodeIdx, p, p.dialog.npcIdx);
				break;
			case 9:
				active = false;
				p.dialog.active = false;
				break;
			case 0:
			{
				active = false;
				p.dialog.active = false;
				if (curLev != 12)
				{
					PlayerMgr.CloseCoopPlayers(p);
				}
				Character playerCharacter = CharMgr.GetPlayerCharacter(p);
				if (playerCharacter != null && playerCharacter.anim.animName == "pray")
				{
					playerCharacter.anim.SetAnimation("prayout");
				}
				break;
			}
			}
			break;
		case 2:
			if (p.levelupFrame > 0f)
			{
				transFrame = 0f;
				break;
			}
			if (p.runeGetFrame > 0f)
			{
				transFrame = 0f;
				break;
			}
			transFrame += Game1.frameTime * 4f;
			if (transFrame > 1f)
			{
				transMode = 0;
			}
			break;
		case 4:
			transFrame += Game1.frameTime * 4f;
			if (transFrame > 1f)
			{
				transMode = 0;
			}
			break;
		}
		for (int i = 0; i < menuLevel.Length; i++)
		{
			menuLevel[i].Update(i, p);
		}
	}
	internal void Draw(float scale)
	{
		if (menuLevel[curLev].showParent > -1 && menuLevel[menuLevel[curLev].showParent].alpha > 0f)
		{
			menuLevel[menuLevel[curLev].showParent].Draw(p, scale);
		}
		for (int i = 0; i < menuLevel.Length; i++)
		{
			if (menuLevel[i].alpha > 0f && menuLevel[curLev].showParent != i)
			{
				menuLevel[i].Draw(p, scale);
			}
		}
	}
	internal void Activate(int p)
	{
		active = true;
		transMode = 2;
		curLev = p;
		transFrame = 0f;
		menuLevel[curLev].selected = 0;
		menuLevel[curLev].alpha = 0f;
	}
