			{
				countBuyConfirmFrame += Game1.frameTime * 2f;
				if (!(countBuyConfirmFrame > 1f))
				{
					base.SelectedUpdate(p);
					return;
				}
				countBuyConfirmFrame = 1f;
			}
		}
		else if (countBuyConfirmFrame > 0f)
		{
			countBuyConfirmFrame -= Game1.frameTime * 2f;
			if (!(countBuyConfirmFrame < 0f))
			{
				base.SelectedUpdate(p);
				return;
			}
			countBuyConfirmFrame = 0f;
		}
		bool flag = false;
		int category = lootDef.category;
		if (category == 4 || category == 7)
		{
			flag = true;
		}
		if (!countBuyConfirm && flag)
		{
			if (p.keyYToggle)
			{
				if (count > 1)
				{
					p.draw.ClickQuantity(0);
					Sound.PlaySelect();
					count--;
				}
				else
				{
					Sound.PlayCancel();
				}
			}
			if (p.keyXInfo)
			{
				switch (storeMode)
