					if (p.playerInv.HasRoom(invLoot, count + 1) && p.gold >= cost * (count + 1))
					{
						p.draw.ClickQuantity(1);
						Sound.PlaySelect();
						count++;
					}
					else
					{
						Sound.PlayCancel();
					}
					break;
				case 1:
