					countBuyConfirm = true;
					countBuyConfirmFrame = 0f;
				}
				break;
			}
			case 1:
			{
				bool showCount = GetShowCount();
				if (!showCount || countBuyConfirm)
				{
					p.drawGoldAdd = cost * count;
					p.drawGoldAddFrame = 3f;
