namespace ProjectTower.player.dialog.levels;
public class IconOffer : DialogMenuLevel
{
	public LootDef[] lootDef;
	public InvLoot[] invLoot;
	public float[] itemAlpha;
	private float scroll;
	public bool active;
	public int selItem;
	public int returnLevel;
	public IconOffer()
	{
		hijackDraw = true;
		hijackUpdate = true;
	}
	public void Init(int returnLevel, Player p)
	{
		scroll = 0f;
		List<int> list = new List<int>();
		List<int> list2 = new List<int>();
		for (int i = 0; i < p.playerInv.inventory.Length; i++)
		{
			InvLoot invLoot = p.playerInv.inventory[i];
			if (invLoot == null || invLoot.category != 7)
			{
				continue;
			}
			LootDef lootDef = LootCatalog.category[7].loot[invLoot.catalogIdx];
			if (lootDef.type != 7)
			{
				int flags = lootDef.flags;
				if ((uint)(flags - 10) <= 3u || (uint)(flags - 23) <= 3u)
				{
					list.Add(invLoot.catalogIdx);
					list2.Add(i);
				}
			}
		}
		this.lootDef = new LootDef[list.Count];
		this.invLoot = new InvLoot[list.Count];
		itemAlpha = new float[list.Count];
		for (int j = 0; j < list.Count; j++)
		{
			this.lootDef[j] = new LootDef(LootCatalog.category[7].loot[list[j]]);
			this.lootDef[j].titleStr = new StringBuilder(this.lootDef[j].title[Game1.language]);
			this.invLoot[j] = new InvLoot();
			this.invLoot[j].InitFromName(this.lootDef[j].name);
			this.lootDef[j].durability = LootCatalog.category[7].loot[list[j]].durability;
			this.invLoot[j].count = p.playerInv.inventory[list2[j]].count;
		}
		if (selItem < 0)
		{
			selItem = 0;
		}
		if (selItem > list.Count - 1)
		{
			selItem = list.Count - 1;
		}
		scroll = 0f;
		this.returnLevel = returnLevel;
	}
	public override void SelectedUpdate(Player p)
	{
		if (selItem >= this.lootDef.Length)
		{
			selItem = 0;
		}
		Character playerCharacter = CharMgr.GetPlayerCharacter(p);
		if (playerCharacter == null)
		{
			return;
		}
		p.playerInv.descScroll -= p.keyRAnalog.Y * Game1.frameTime * 100f;
		if (p.playerInv.descScroll < 0f)
		{
			p.playerInv.descScroll = 0f;
		}
		if (p.keyUp)
		{
			p.playerInv.descScroll = 0f;
			Sound.PlaySelect();
			selItem -= 4;
			if (selItem < 0)
			{
				selItem = 0;
			}
		}
		if (p.keyDown)
		{
			p.playerInv.descScroll = 0f;
			Sound.PlaySelect();
			selItem += 4;
			if (selItem >= this.lootDef.Length)
			{
				selItem = this.lootDef.Length - 1;
				if (selItem < 0)
				{
					selItem = 0;
				}
			}
		}
		if (p.keyLeft)
		{
			p.playerInv.descScroll = 0f;
			Sound.PlaySelect();
			selItem--;
			if (selItem < 0)
			{
				selItem = 0;
			}
		}
		if (p.keyRight)
		{
			p.playerInv.descScroll = 0f;
			Sound.PlaySelect();
			selItem++;
			if (selItem >= this.lootDef.Length)
			{
				selItem = this.lootDef.Length - 1;
				if (selItem < 0)
				{
					selItem = 0;
				}
			}
		}
		if (p.keyBCancel)
		{
			Sound.PlayCancel();
			p.dialog.menuMgr.DoLevelTrans(returnLevel);
		}
		if (p.keyAccept && selItem > -1 && selItem < this.lootDef.Length)
		{
			int sanctuaryIn = MapMgr.sanctuaryMgr.GetSanctuaryIn(playerCharacter);
			if (sanctuaryIn > -1)
			{
				int num = 0;
				if (this.lootDef.Length != 0)
				{
					switch (this.lootDef[selItem].flags)
					{
					case 13:
						num = 3;
						break;
					case 10:
						num = 2;
						break;
					case 11:
						num = 1;
						break;
					case 12:
						num = 4;
						break;
					case 23:
						num = 5;
						break;
					case 24:
						num = 6;
						break;
					case 25:
						num = 7;
						break;
					case 26:
						num = 8;
						break;
					}
					bool flag = false;
					if (num > 0)
					{
						int num2 = MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn].AddMerchant(num);
						if (num2 > -1)
						{
							p.sanctuaryPilgrim[sanctuaryIn, num2] = num;
							p.SetSanctuaryBonuses(p.zoneEnter);
							flag = true;
						}
						else
						{
							switch (num2)
							{
							case -1:
								HUD.AddModalDialog(p.ID, LocStrings.GetLocStr(460), LocStrings.GetLocStr(461));
								break;
							case -2:
								HUD.AddModalDialog(p.ID, LocStrings.GetLocStr(460), LocStrings.GetLocStr(462));
								break;
							}
							Sound.PlayCancel();
						}
					}
					if (flag)
					{
						Sound.PlayAccept();
						for (int i = 0; i < p.playerInv.inventory.Length; i++)
						{
							InvLoot invLoot = p.playerInv.inventory[i];
							if (invLoot == null || invLoot.category != 7)
							{
								continue;
							}
							LootDef lootDef = LootCatalog.category[7].loot[invLoot.catalogIdx];
							if (lootDef.type != 7 && lootDef.flags == this.lootDef[selItem].flags)
							{
								p.playerInv.inventory[i].count--;
								if (p.playerInv.inventory[i].count <= 0)
								{
									p.playerInv.inventory[i] = null;
								}
								break;
							}
						}
						Init(returnLevel, p);
					}
				}
			}
		}
		for (int j = 0; j < itemAlpha.Length; j++)
		{
			if (j == selItem)
