		public WorkItem(string s, int idx)
		{
			try
			{
				string[] array = s.Split('/');
				loot = new InvLoot();
				loot.InitFromName(array[0]);
				string[] array2 = array[1].Split(' ');
				count = Convert.ToInt32(array2[0]);
				devotion = Convert.ToInt32(array2[1]);
				title = new StringBuilder(LootCatalog.category[loot.category].loot[loot.catalogIdx].title[Game1.language]);
				alpha = 0f;
				this.idx = idx;
			}
			catch
			{
				count = 0;
				devotion = 0;
				loot = null;
				alpha = 0f;
				title = null;
				this.idx = idx;
			}
		}
	}
