	public void TurnInItem(Player p)
	{
		int count = workItem[selItem].count;
		p.playerInv.GetMaterialDefCount(workItem[selItem].loot.category, workItem[selItem].loot.catalogIdx);
		Character playerCharacter = CharMgr.GetPlayerCharacter(p);
		if (playerCharacter != null)
		{
			int sanctuaryIn = MapMgr.sanctuaryMgr.GetSanctuaryIn(playerCharacter);
			if (sanctuaryIn > -1)
			{
				Sanctuary sanctuary = MapMgr.sanctuaryMgr.sanctuaries[sanctuaryIn];
				for (int i = 0; i < count; i++)
				{
					p.playerInv.UseMaterialDef(workItem[selItem].loot.category, workItem[selItem].loot.catalogIdx);
				}
				p.creedLevel[sanctuary.creed] += workItem[selItem].devotion;
				if (p.creedLevel[sanctuary.creed] >= 7)
				{
					Achievements.AwardAchievement(34);
					p.creedLevel[sanctuary.creed] = 7;
				}
				p.creedUnlocks[sanctuary.creed, ((WorkUpgrade)p.dialog.menuMgr.menuLevel[23]).selItem]++;
				string text = WorkTitle(sanctuary, workItem[selItem]);
				p.flags.Add(text);
			}
		}
		Init(p, reserveList);
	}
	private static string WorkTitle(Sanctuary sanct, WorkItem wItem)
	{
		return "#wi#_" + sanct.creed + "_" + wItem.loot.name + "_" + wItem.count + "_" + wItem.idx;
	}
	public static void PurgeWork(Player p, int creed)
	{
		GameConsole.WriteLine("Purging " + creed + "...");
		for (int i = 0; i < 4; i++)
		{
			p.creedUnlocks[creed, i] = 0;
		}
		int num = 0;
		while (true)
		{
			num++;
			bool flag = false;
			for (int j = 0; j < p.flags.Count; j++)
			{
				if (!p.flags[j].StartsWith("#wi#_"))
				{
					continue;
				}
				string value = p.flags[j].Substring("#wi#_".Length, 1);
				try
				{
					if (Convert.ToInt32(value) == creed)
					{
						GameConsole.WriteLine("Purged " + p.flags[j] + ".");
						p.flags.RemoveAt(j);
						flag = true;
						break;
					}
				}
				catch
				{
				}
			}
			if (!flag)
			{
				break;
			}
			if (num > 100)
			{
				GameConsole.WriteLine("Overload.");
				break;
			}
		}
		GameConsole.WriteLine("Purging complete.");
	}
