	private void UpdateWordMap()
	{
		wordMap = new List<int>();
		List<string> list = new List<string>();
		for (int i = 0; i < RuneMessage.words[selLetter].Length; i++)
		{
			if (!list.Contains(RuneMessage.words[selLetter][i].locTextStr))
			{
