	}
	public override void SelectedUpdate(Player p)
	{
		if (messageFrame > 0f)
		{
			messageFrame -= Game1.frameTime * 2f;
		}
		float num = 0f;
		int profIdx = InputMgr.GetProfIdx(p);
		InputProfile inputProfile = InputMgr.inputProfile[profIdx];
		if (inputProfile.keyMouseEnable && !inputProfile.mouseEnable)
		{
			num = 0f - (float)selLetter / (float)RuneMessage.letters.Length * ((float)Math.PI * 2f);
		}
		float num2;
		for (num2 = num - alphabetRotate; num2 > (float)Math.PI; num2 -= (float)Math.PI * 2f)
		{
		}
		for (; num2 < -(float)Math.PI; num2 += (float)Math.PI * 2f)
		{
		}
		alphabetRotate += num2 * Game1.realTime * 5f;
		while (alphabetRotate > (float)Math.PI * 2f)
		{
			alphabetRotate -= (float)Math.PI * 2f;
		}
		while (alphabetRotate < 0f)
		{
			alphabetRotate += (float)Math.PI * 2f;
		}
		switch (mode)
		{
		case 0:
		{
			if (dictionaryAlpha > 0f)
			{
				dictionaryAlpha -= Game1.realTime * 6f;
				if (dictionaryAlpha < 0f)
				{
					dictionaryAlpha = 0f;
				}
			}
			bool flag = false;
			if (inputProfile.keyMouseEnable && !inputProfile.mouseEnable)
			{
				flag = true;
				int num3 = selLetter;
				if (p.keyDown)
				{
					selLetter = (selLetter + 1) % RuneMessage.letters.Length;
				}
				if (p.keyUp)
				{
					selLetter = (selLetter + (RuneMessage.letters.Length - 1)) % RuneMessage.letters.Length;
				}
				if (num3 != selLetter)
				{
					Sound.PlaySelect();
					wordMap = null;
				}
			}
			if (!flag)
			{
				gamePadVec = GamePad.GetState((PlayerIndex)p.gamepadIdx, GamePadDeadZone.None).ThumbSticks.Left * new Vector2(1f, -1f);
				p.keyDownHoldFrame = 0f;
				p.keyUpHoldFrame = 0f;
				gamePadAngle = -1f;
				if (gamePadVec.Length() > 0.9f)
				{
					gamePadAngle = Trig.GetAngle(gamePadVec, default);
					drawGamePadAngle = gamePadAngle;
				}
				if (gamePadAngle > -1f)
				{
					for (int i = 0; i < RuneMessage.letters.Length; i++)
					{
						float num4 = (float)i / (float)RuneMessage.letters.Length * ((float)Math.PI * 2f);
						new Vector2((float)Math.Cos(num4), (float)Math.Sin(num4));
						float num5 = num4 - gamePadAngle;
						if (num5 < -6f)
						{
							num5 += (float)Math.PI * 2f;
						}
						num5 = Math.Abs(num5);
						num5 *= 5f;
						num5 = ((!(num5 < 1f)) ? 0f : (1f - num5));
						if (num5 > 0.35f)
						{
							if (i != selLetter)
							{
								Sound.PlaySelect();
								wordMap = null;
							}
							selLetter = i;
						}
					}
				}
			}
			if (p.keyAccept)
			{
				if (message[0].messageCurrentWord < 6)
				{
					mode = 1;
					selected = 0;
				}
				Sound.PlayConfirm();
			}
			if (p.keyXInfo)
			{
				if (message[0].messageCurrentWord > 0)
				{
					message[1].CopyFrom(message[0]);
					message[0].messageCurrentWord--;
					messageFrame = 1f;
				}
				Sound.PlayCancel();
			}
			if (p.keyYToggle)
			{
				Sound.PlayConfirm();
				bool flag2 = false;
				int num6 = message[0].messageCurrentWord - 1;
				if (num6 > 0)
				{
					char c = RuneMessage.words[message[0].messageLetter[num6]][message[0].messageWord[num6]].locText[0];
					if (c == '!' || c == '.' || c == '?')
					{
						flag2 = true;
					}
				}
				if (flag2)
				{
					grammaticallyCorrect = true;
					p.dialog.menuMgr.DoLevelTrans(10);
				}
				else
				{
					grammaticallyCorrect = false;
					p.dialog.menuMgr.DoLevelTrans(21);
				}
			}
			if (p.keyBCancel)
			{
				p.dialog.menuMgr.DoLevelTrans(11);
				Sound.PlayCancel();
			}
			break;
		}
		case 1:
			if (wordMap == null)
			{
				UpdateWordMap();
			}
			if (dictionaryAlpha < 1f)
			{
				dictionaryAlpha += Game1.realTime * 6f;
				if (dictionaryAlpha > 1f)
				{
					dictionaryAlpha = 1f;
				}
			}
			if (p.keyLeft)
			{
				if (selected >= 13)
				{
					selected -= 13;
				}
				Sound.PlaySelect();
			}
			if (p.keyRight)
			{
				if (selected + 13 < wordMap.Count)
				{
					selected += 13;
				}
				Sound.PlaySelect();
			}
			if (p.keyUp)
			{
				if (selected > 0)
				{
					selected--;
					if (selected % 13 == 12)
					{
						selected++;
					}
				}
				Sound.PlaySelect();
			}
			if (p.keyDown)
			{
				if (selected < wordMap.Count - 1)
				{
					selected++;
					if (selected % 13 == 0)
					{
						selected--;
					}
				}
				Sound.PlaySelect();
			}
			if (p.keyBCancel)
			{
				Sound.PlayCancel();
				mode = 0;
			}
			if (p.keyAccept)
			{
				Sound.PlayAccept();
				mode = 0;
				message[1].CopyFrom(message[0]);
				message[0].messageWord[message[0].messageCurrentWord] = wordMap[selected];
				message[0].messageLetter[message[0].messageCurrentWord] = selLetter;
				message[0].messageCurrentWord++;
				messageFrame = 1f;
			}
			break;
		}
		if (wordMap == null)
		{
			UpdateWordMap();
		}
		base.SelectedUpdate(p);
	}
	internal string GetMessageString()
	{
		string text = "";
		for (int i = 0; i < message[0].messageCurrentWord; i++)
		{
			bool flag = i == 0;
			if (i > 0)
			{
				char c = RuneMessage.words[message[0].messageLetter[i - 1]][message[0].messageWord[i - 1]].locText[0];
				if (c == '!' || c == '.' || c == '?')
				{
					flag = true;
				}
			}
			StringBuilder stringBuilder = (flag ? RuneMessage.words[message[0].messageLetter[i]][message[0].messageWord[i]].firstWordEnglistText : RuneMessage.words[message[0].messageLetter[i]][message[0].messageWord[i]].englistText);
			if (i > 0)
			{
				text += " ";
			}
			text += stringBuilder;
		}
		return text;
	}
