	{
		int npcIdx = p.dialog.npcIdx;
		if (npcIdx <= -1 || npcIdx >= CharMgr.character.Length)
		{
			return;
		}
		Character character = CharMgr.character[npcIdx];
		if (character.grabbedBy <= -1)
		{
			int num = CharMgr.AddCharacter("marauder", character.loc, character.face, -1, 1);
			if (num > -1)
			{
				character.grabbedBy = num;
				CharMgr.character[num].grabbing = character.ID;
				character.anim.SetAnimation("captainstabbed");
				character.aggrod = true;
				character.ethereal = true;
			}
		}
	}
	public static void DoStore(Player p, string[] store)
	{
		List<string> list = new List<string>();
		for (int i = 0; i < store.Length; i++)
		{
			if (store[i].Contains(' '))
			{
				try
				{
					string[] array = store[i].Split(' ');
					if (array[0] == "returnlevel" && array.Length >= 2)
					{
						p.dialog.dialogCatNodeIdx = DialogMgr.dialogList[p.dialog.dialogCatIdx].GetNodeIdx(array[1]);
					}
				}
				catch
				{
				}
