		{
			return;
		}
		NPCDialog nPCDialog = DialogMgr.dialogList[dialogIdx];
		if (nodeIdx < 0 || nodeIdx > nPCDialog.nodeList.Length - 1)
		{
			return;
		}
		DialogNode dialogNode = nPCDialog.nodeList[nodeIdx];
		for (int i = 0; i < dialogNode.precheckFlagStr.Length; i++)
		{
			if (dialogNode.precheckFlagStr[i] != "" && PlayerMgr.GetMainPlayerFlag(dialogNode.precheckFlagStr[i]))
			{
				nodeIdx = nPCDialog.GetNodeIdx(dialogNode.precheckFlagGoto[i]);
				if (nodeIdx > -1)
				{
					dialogNode = nPCDialog.nodeList[nodeIdx];
					i = -1;
				}
			}
		}
		p.dialog.dialogCatIdx = dialogIdx;
		p.dialog.dialogCatNodeIdx = nodeIdx;
		if (dialogNode.postSetFlagStr != "")
		{
			PlayerMgr.SetMainPlayerFlag(dialogNode.postSetFlagStr);
